1	import * as THREE from "three";
2	import { EnvSetup } from "../../app/EnvSetup.js";
3	import { SceneObject } from "../../core/SceneObject.js";
4	import type {
5	  GravityBallsObjectOptions,
6	  GravityBallsTweenProps,
7	} from "../../types/object.types.js";
8	import { Helpers } from "../../utils/Helpers.js";
9	
10	interface BallInfo {
11	  color: string;
12	  radius: number;
13	  radiusStart: number;
14	  radiusDeincrement: number;
15	  startX: number;
16	  startY: number;
17	  startZ: number;
18	  isXNegative: number;
19	  isZNegative: number;
20	  vx: number;
21	  vxMult: number;
22	  vy: number;
23	  vyMult: number;
24	  vz: number;
25	  vzMult: number;
26	  ID: number;
27	  bounced: boolean;
28	  startGravity: number;
29	  gravity: number;
30	  sphere: THREE.Mesh<THREE.CircleGeometry, THREE.MeshBasicMaterial>;
31	}
32	
33	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
34	  private static readonly COLORS: ReadonlyArray<string> = [
35	    "#bada55",
36	    "#bada55",
37	    "#bada55",
38	    "bada55",
39	  ];
40	  private static readonly RADIUS = 3;
41	  private static readonly DOTS_PER_INTERVAL = 5;
42	  private static readonly SPAWN_INTERVAL_SEC = 0.015;
43	  private static readonly FLOOR_LEVEL = -100;
44	  private static readonly FLOOR_DIMENSIONS = 1500;
45	  /** Original gravity-balls coordinate system (~1500 unit floor) shrunk to fit rocket scale. */
46	  private static readonly INNER_SCALE_DEFAULT = 0.05;
47	  /** `?debug=1` 모드에서 점·플로어가 인터랙션·인트로에 가려지지 않게 키우는 배수. */
48	  private static readonly INNER_SCALE_DEBUG = 0.2;
49	  private static readonly DEBUG_RENDER_ORDER = 9999;
50	  private static readonly DEBUG_FLOOR_COLOR = "#ff00ff";
51	
52	  private readonly _isDebug = EnvSetup.hasQueryFlag("debug", "1");
53	
54	  private _options: Partial<GravityBallsObjectOptions> = {};
55	  private _built = false;
56	  private _innerGroup: THREE.Group | null = null;
57	  private _floor: THREE.Mesh<THREE.BoxGeometry, THREE.MeshLambertMaterial> | null =
58	    null;
59	  /** Floor의 부모 (scene root에 attach되어 외부 transform 변경에 영향받지 않음). */
60	  private _floorParent: THREE.Object3D | null = null;
61	  private _spheresInfo = new Map<number, BallInfo>();
62	  private _sphereIndex = 0;
63	  private _canvasMouse = new THREE.Vector3(0, 0, 0);
64	  private _spawnAccumulator = 0;
65	  private _innerScale = GravityBalls.INNER_SCALE_DEFAULT;
66	  private _trackedEmitterObject: THREE.Object3D | null = null;
67	  private _effectiveFloorLevel = GravityBalls.FLOOR_LEVEL;
68	
69	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
70	    if (props != null) this._options = { ...this._options, ...props };
71	    return this;
72	  }
73	
74	  override getAnimationTarget(): THREE.Object3D | null {
75	    return this.getTimelineRoot();
76	  }
77	
78	  override getTweenApplyMode(): "mergeAndSync" {
79	    return "mergeAndSync";
80	  }
81	
82	  protected override getOptions(): Record<string, unknown> {
83	    return this._options as Record<string, unknown>;
84	  }
85	
86	  protected override applyVisibility(visible: boolean): void {
87	    const root = this.getTimelineRoot();
88	    if (!root) return;
89	    root.visible = visible;
90	    if (!visible) this._clearAllSpheres();
91	  }
92	
93	  override runObject(): void {
94	    const ctx = this._context;
95	    if (!ctx?.scene) return;
96	
97	    const root = this.ensureTimelineRoot("gravityBallsRoot");
98	    if (!root) return;
99	
100	    const attachTo = this._options.attachTo;
101	    const offset = this._options.offset ?? { x: 0, y: 0, z: 0 };
102	    const p = this._options.position ?? { x: 0, y: 0, z: 0 };
103	    const r = this._options.rotation ?? { x: 0, y: 0, z: 0 };
104	    const s = this._options.scale ?? { x: 1, y: 1, z: 1 };
105	
106	    if (attachTo && typeof ctx.getObject === "function") {
107	      const target = ctx.getObject(attachTo);
108	      if (target instanceof THREE.Object3D) {
109	        target.add(root);
110	        root.position.set(offset.x ?? 0, offset.y ?? 0, offset.z ?? 0);
111	      } else {
112	        root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
113	      }
114	    } else {
115	      root.position.set(p.x ?? 0, p.y ?? 0, p.z ?? 0);
116	    }
117	
118	    Helpers.applyRotationDeg(root, r);
119	    root.scale.set(s.x ?? 1, s.y ?? 1, s.z ?? 1);
120	
121	    this._innerScale = this._isDebug
122	      ? GravityBalls.INNER_SCALE_DEBUG
123	      : GravityBalls.INNER_SCALE_DEFAULT;
124	
125	    const inner = new THREE.Group();
126	    inner.name = "gravityBallsInner";
127	    inner.scale.setScalar(this._innerScale);
128	    root.add(inner);
129	    this._innerGroup = inner;
130	
131	    if (this._options.trackEmitter && typeof ctx.getObject === "function") {
132	      const emitter = ctx.getObject(this._options.trackEmitter);
133	      if (emitter instanceof THREE.Object3D) {
134	        this._trackedEmitterObject = emitter;
135	      }
136	    }
137	
138	    this._buildFloor();
139	    this._built = true;
140	  }
141	
142	  private static readonly _tmpV3A = new THREE.Vector3();
143	  private static readonly _tmpV3B = new THREE.Vector3();
144	
145	  override runUpdate(deltaTime: number): void {
146	    if (!this._built) return;
147	    const root = this.getTimelineRoot();
148	    if (!root) return;
149	    if (this._isDebug && !root.visible) root.visible = true;
150	    if (!root.visible) return;
151	
152	    if (this._trackedEmitterObject) {
153	      root.getWorldPosition(GravityBalls._tmpV3A);
154	      this._trackedEmitterObject.getWorldPosition(GravityBalls._tmpV3B);
155	      this._canvasMouse.set(
156	        (GravityBalls._tmpV3B.x - GravityBalls._tmpV3A.x) / this._innerScale,
157	        (GravityBalls._tmpV3B.y - GravityBalls._tmpV3A.y) / this._innerScale,
158	        (GravityBalls._tmpV3B.z - GravityBalls._tmpV3A.z) / this._innerScale,
159	      );
160	    }
161	
162	    this._spawnAccumulator += deltaTime;
163	    while (this._spawnAccumulator >= GravityBalls.SPAWN_INTERVAL_SEC) {
164	      for (let i = 0; i < GravityBalls.DOTS_PER_INTERVAL; i += 1) {
165	        this._initDot();
166	      }
167	      this._spawnAccumulator -= GravityBalls.SPAWN_INTERVAL_SEC;
168	    }
169	
170	    for (const info of Array.from(this._spheresInfo.values())) {
171	      this._drawDot(info);
172	    }
173	  }
174	
175	  override dispose(): void {
176	    this._clearAllSpheres();
177	    if (this._floor) {
178	      this._floor.geometry.dispose();
179	      this._floor.material.dispose();
180	      // Floor는 scene root에 re-parent되어 있으므로 _floorParent에서 직접 제거
181	      (this._floorParent ?? this._floor.parent)?.remove(this._floor);
182	      this._floor = null;
183	      this._floorParent = null;
184	    }
185	    if (this._innerGroup) {
186	      this._innerGroup.parent?.remove(this._innerGroup);
187	      this._innerGroup = null;
188	    }
189	    this._built = false;
190	    super.dispose();
191	  }
192	
193	  private _buildFloor(): void {
194	    const inner = this._innerGroup;
195	    const ctx = this._context;
196	    if (!inner || !ctx?.scene) return;
197	    const geometry = new THREE.BoxGeometry(
198	      GravityBalls.FLOOR_DIMENSIONS,
199	      3,
200	      GravityBalls.FLOOR_DIMENSIONS,
201	    );
202	    const material = new THREE.MeshLambertMaterial({
203	      color: this._isDebug ? GravityBalls.DEBUG_FLOOR_COLOR : "#000000",
204	      wireframe: this._isDebug,
205	    });
206	    material.depthWrite = false;
207	    material.transparent = true;
208	    material.opacity = this._isDebug ? 0.6 : 0.2;
209	    const floor = new THREE.Mesh(geometry, material);
210	    floor.position.y = GravityBalls.FLOOR_LEVEL - GravityBalls.RADIUS / 2;
211	    floor.position.z = 0;
212	    if (this._isDebug) floor.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
213	    // 1) Inner group에서 정확한 local 좌표·INNER_SCALE을 적용해 일단 부착
214	    inner.add(floor);
215	    inner.updateMatrixWorld(true);
216	    // 2) Scene root로 re-parent (world transform 보존). 이후 inner/timeline root가
217	    //    Theatre·인트로에 의해 움직여도 floor는 boot 시점 world 위치에 고정됨.
218	    ctx.scene.attach(floor);
219	
220	    const floorWorldY = this._options.floorWorldY;
221	    if (floorWorldY != null) {
222	      const root = this.getTimelineRoot()!;
223	      root.getWorldPosition(GravityBalls._tmpV3A);
224	      this._effectiveFloorLevel =
225	        (floorWorldY - GravityBalls._tmpV3A.y) / this._innerScale;
226	      floor.position.y = floorWorldY;
227	    }
228	
229	    this._floor = floor;
230	    this._floorParent = ctx.scene;
231	  }
232	
233	  private _initDot(): void {
234	    const inner = this._innerGroup;
235	    if (!inner) return;
236	    const radius = GravityBalls.RADIUS;
237	    const colorIdx = this._random(0, 4);
238	    const color = GravityBalls.COLORS[colorIdx] ?? "#bada55";
239	    const radiusStart = radius;
240	    const radiusDeincrement = radius * -0.002;
241	    const startX = this._canvasMouse.x;
242	    let startY = this._canvasMouse.y;
243	    const startZ = this._canvasMouse.z;
244	    if (startY < this._effectiveFloorLevel - radiusStart / 2) {
245	      startY = this._effectiveFloorLevel - radiusStart / 2;
246	    }
247	    const isXNegative = this._random(1, 2);
248	    const isZNegative = this._random(1, 2);
249	    const vx =
250	      isXNegative === 1
251	        ? this._random(0, 50) * -0.15
252	        : this._random(0, 50) * 0.15;
253	    const vxMult = this._random(10, 20) * 0.15;
254	    const vy = this._random(-10, 20);
255	    const vyMult = this._random(4, 6) * -0.1;
256	    const vz =
257	      isZNegative === 1
258	        ? this._random(-25, 25) * -0.4
259	        : this._random(-25, 25) * 0.4;
260	    const vzMult = this._random(10, 20) * 0.1;
261	    this._sphereIndex += 1;
262	    const ID = this._sphereIndex;
263	    const startGravity = 10;
264	    const geometry = new THREE.CircleGeometry(radius, 20);
265	    const material = new THREE.MeshBasicMaterial({
266	      color,
267	      side: THREE.DoubleSide,
268	    });
269	    if (this._isDebug) {
270	      material.depthTest = false;
271	      material.depthWrite = false;
272	      material.transparent = true;
273	    }
274	    const sphere = new THREE.Mesh(geometry, material);
275	    if (this._isDebug) sphere.renderOrder = GravityBalls.DEBUG_RENDER_ORDER;
276	    inner.add(sphere);
277	
278	    this._spheresInfo.set(ID, {
279	      color,
280	      radius,
281	      radiusStart,
282	      radiusDeincrement,
283	      startX,
284	      startY,
285	      startZ,
286	      isXNegative,
287	      isZNegative,
288	      vx,
289	      vxMult,
290	      vy,
291	      vyMult,
292	      vz,
293	      vzMult,
294	      ID,
295	      bounced: false,
296	      startGravity,
297	      gravity: startGravity,
298	      sphere,
299	    });
300	  }
301	
302	  private _drawDot(info: BallInfo): void {
303	    info.sphere.scale.x += info.radiusDeincrement;
304	    info.sphere.scale.y += info.radiusDeincrement;
305	    info.sphere.scale.z += info.radiusDeincrement;
306	    info.startX += info.vx * 0.6;
307	    info.startY -= info.vy * 0.5;
308	    info.startZ -= info.vz * 0.6;
309	    info.sphere.position.x = info.startX;
310	    info.sphere.position.y = info.startY;
311	    info.sphere.position.z = info.startZ;
312	
313	    if (
314	      info.sphere.position.y <
315	      this._effectiveFloorLevel - info.radiusStart / 2
316	    ) {
317	      if (!info.bounced) {
318	        info.vx *= info.vxMult;
319	        info.vz *= info.vzMult;
320	      } else {
321	        info.vx *= 0.95;
322	        info.vz *= 0.95;
323	      }
324	      const half = GravityBalls.FLOOR_DIMENSIONS / 2;
325	      const outsideFloor =
326	        info.sphere.position.x > half ||
327	        info.sphere.position.x < -half ||
328	        info.sphere.position.z > half ||
329	        info.sphere.position.z < -half;
330	      if (!outsideFloor) {
331	        info.vy *= info.vyMult;
332	        info.sphere.position.y =
333	          this._effectiveFloorLevel + info.radiusStart * info.sphere.scale.x;
334	      } else {
335	        info.gravity = info.startGravity / 4;
336	        info.startY -= info.vy * 0.01;
337	        info.sphere.position.y =
338	          info.startY + (20 - info.radiusStart * info.sphere.scale.x);
339	      }
340	      info.bounced = true;
341	    }
342	
343	    info.vy += info.gravity;
344	
345	    if (info.sphere.scale.y <= 0.1) {
346	      this._spheresInfo.delete(info.ID);
347	      info.sphere.parent?.remove(info.sphere);
348	      info.sphere.geometry.dispose();
349	      info.sphere.material.dispose();
350	    }
351	  }
352	
353	  private _clearAllSpheres(): void {
354	    for (const info of this._spheresInfo.values()) {
355	      info.sphere.parent?.remove(info.sphere);
356	      info.sphere.geometry.dispose();
357	      info.sphere.material.dispose();
358	    }
359	    this._spheresInfo.clear();
360	  }
361	
362	  private _random(min: number, max: number): number {
363	    return Math.floor(Math.random() * max) + min;
364	  }
365	}
