245	    const initialState = mergeAboutTheatreStateSources(fileState, savedState);
246	    const project = TheatreProjectSession.open<
247	      AboutTheatreValue,
248	      AboutTheatreProps
249	    >(
250	      ABOUT_THEATRE_PROJECT_ID,
251	      initialState ? { state: initialState } : undefined,
252	    );
253	    await project.ready;
254	    ABOUT_THEATRE_SHEET_IDS.forEach((sheetId) => {
255	      const sheet = TheatreSheetSession.open(project, sheetId);
256	      const object = sheet.object(
257	        ABOUT_THEATRE_OBJECT_ID,
258	        this._readSceneValues(),
259	        {
260	          reconfigure: true,
261	        },
262	      );
263	      const sequence = TheatreSequenceSession.get(sheet);
264	      this._sheetById.set(sheetId, sheet);
265	      this._objectBySheetId.set(sheetId, object);
266	      this._sequenceBySheetId.set(sheetId, sequence);
267	    });
268	    if (!this._sheetById.has(PRIMARY_SHEET_ID)) {
269	      throw new Error("Primary about theatre sheet was not created.");
270	    }
271	    this._attachSheet(PRIMARY_SHEET_ID);
272	    this._unsubscribeSelection = TheatreStudioService.bindSelectionChange(
273	      (selection) => {
274	        this._syncAuthorSheetFromStudioSelection(selection);
275	      },
276	    );
277	
278	    this._bindControls();
279	    this._renderSheetSelector();
280	    this._renderMatchPrevButton();
281	    if (this._currentObject) {
282	      this._applyState(this._currentObject.value);
283	    }
284	    this._hooks.onModeChange("author");
285	    this._hooks.onPlaybackChange(this._playing);
286	    this._renderExportButton();
287	    this._renderStatus(
288	      savedState
289	        ? `SAVEFILE MERGED (${ABOUT_THEATRE_SHEET_IDS.length} SHEETS)`
290	        : fileState
291	        ? `FILE SAVEFILE LOADED (${ABOUT_THEATRE_SHEET_IDS.length} SHEETS)`
292	        : `THEATRE READY (${ABOUT_THEATRE_SHEET_IDS.length} SHEETS)`,
293	    );
294	  }
295	
296	  private _attachSheet(sheetId: AboutTheatreSheetId): void {
297	    const sheet = this._sheetById.get(sheetId);
298	    const object = this._objectBySheetId.get(sheetId);
299	    const sequence = this._sequenceBySheetId.get(sheetId);
300	    if (!sheet || !object || !sequence) return;
301	    this._unsubscribeValues?.();
302	    this._unsubscribeValues = null;
303	    this._unsubscribePlaying?.();
304	    this._unsubscribePlaying = null;
305	    this._authorSheetId = sheetId;
306	    this._unsubscribeValues = TheatrePlaybackService.bindValues(
307	      object,
308	      (values) => {
309	        if (this._disposed) return;
310	        if (sheetId !== this._authorSheetId) return;
311	        this._applyState(values);
312	        this._schedulePersistSaveFileSnapshot("AUTOSAVE FAILED");
313	      },
314	    );
315	    this._unsubscribePlaying = TheatrePlaybackService.bindPlaying(
316	      sequence,
317	      (playing) => {
318	        if (sheetId !== this._authorSheetId) return;
319	        this._playing = playing;
320	        this._hooks.onPlaybackChange(playing);
321	      },
322	    );
323	    this._syncStudioSelection(sheet, object);
324	    this._applyState(object.value);
325	  }
326	
327	  private get _currentObject(): AboutTheatreObject | null {
328	    return this._objectBySheetId.get(this._authorSheetId) ?? null;
329	  }
330	
331	  private _syncStudioSelection(
332	    sheet: TheatreSheetPort<AboutTheatreValue, AboutTheatreProps>,
333	    object: AboutTheatreObject,
334	  ): void {
335	    this._syncingStudioSelection = true;
336	    try {
337	      TheatreStudioService.setSelection([sheet, object]);
338	    } finally {
339	      this._syncingStudioSelection = false;
340	    }
341	  }
342	
343	  private _syncAuthorSheetFromStudioSelection(
344	    selection: TheatreSelectionItemPort[],
345	  ): void {
346	    if (this._syncingStudioSelection) return;
347	    const nextSheetId = this._findSelectedSheetId(selection);
348	    if (!nextSheetId) return;
349	    if (nextSheetId === this._authorSheetId) return;
350	    this._attachSheet(nextSheetId);
351	    this._syncSheetSelector();
352	    this._renderStatus(`ACTIVE SHEET ${nextSheetId.toUpperCase()}`);
353	  }
354	
355	  private _findSelectedSheetId(
356	    selection: TheatreSelectionItemPort[],
357	  ): AboutTheatreSheetId | null {
358	    for (const [sheetId, sheet] of this._sheetById.entries()) {
359	      if (selection.includes(sheet)) return sheetId;
360	    }
361	    for (const [sheetId, object] of this._objectBySheetId.entries()) {
362	      if (selection.includes(object)) return sheetId;
363	    }
364	    return null;
365	  }
366	
367	  private _bindControls(): void {
368	    this._controls.addEventListener("start", this._onControlsStart);
369	    this._controls.addEventListener("end", this._onControlsEnd);
370	    this._controls.addEventListener("change", this._onControlsChange);
371	  }
372	
373	  private _recordStart(): void {
374	    if (this._playing) return;
375	    this._sampling = true;
376	    this._recordScrub = TheatreStudioService.createScrub<
377	      AboutTheatreValue,
378	      AboutTheatreProps
379	    >();
380	    this._recordFrame(true);
381	  }
382	
383	  private _recordEnd(): void {
384	    if (this._playing) return;
385	    this._recordFrame(true);
386	    this._sampling = false;
387	    this._recordScrub?.commit();
388	    this._recordScrub = null;
389	    this._schedulePersistSaveFileSnapshot("AUTOSAVE FAILED");
390	  }
391	
392	  private _recordFrame(force = false): void {
393	    if (this._playing) return;
394	    if (!force && !this._sampling) return;
395	    const object = this._currentObject;
396	    const scrub = this._recordScrub;
397	    if (!object || !scrub) return;
398	
399	    const now = performance.now();
400	    if (!force && now - this._lastSampleAt < FRAME_MS) return;
401	    this._lastSampleAt = now;
402	
403	    const values = this._readCameraValues();
404	    const cameraProps = object.props.camera;
405	    const cameraScrub = scrub as unknown as AboutTheatreScrubCameraPort;
406	    cameraScrub.capture(({ set }) => {
407	      set(cameraProps, values.camera);
408	    });
409	  }
410	
411	  private _readSceneValues(): AboutTheatreValue {
412	    const state = this._rig.read(this._engine);
413	    return pickAboutTheatreValue(state);
414	  }
415	
416	  private _readCameraValues(): AboutCameraTheatreValue {
417	    const state = this._rig.read(this._engine);
418	    return {
419	      camera: state.camera,
420	    };
421	  }
422	
423	  private _setAuthorSheetId(sheetId: string): void {
424	    if (!this._isTheatreSheetId(sheetId)) return;
425	    if (this._authorSheetId === sheetId) return;
426	    this._attachSheet(sheetId);
427	    this._syncSheetSelector();
428	    this._renderStatus(`ACTIVE SHEET ${sheetId.toUpperCase()}`);
429	  }
430	
431	  private _matchFromPrevious(): void {
432	    const currentIndex = ABOUT_THEATRE_SHEET_IDS.indexOf(this._authorSheetId);
433	    if (currentIndex <= 0) {
434	      this._renderStatus("NO PREVIOUS SHEET");
435	      return;
436	    }
437	    const previousSheetId = ABOUT_THEATRE_SHEET_IDS[currentIndex - 1];
438	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
439	    const previousSequence = this._sequenceBySheetId.get(previousSheetId) ?? null;
440	    const currentObject = this._currentObject;
441	    const currentSequence = this._sequenceBySheetId.get(this._authorSheetId) ?? null;
442	    if (!previousObject || !previousSequence || !currentObject || !currentSequence) {
443	      this._renderStatus("MATCH FAILED");
444	      return;
445	    }
446	
447	    const previousEndValues = this._readSheetEndValues(
448	      previousSheetId,
449	      previousObject,
450	      previousSequence,
451	    );
452	    if (!previousEndValues) {
453	      this._renderStatus("MATCH FAILED");
454	      return;
455	    }
456	
457	    this._writeMatchStartKeyframe(
458	      currentObject,
459	      currentSequence,
460	      previousEndValues,
461	    );
462	    this._applyState(previousEndValues);
463	    this._schedulePersistSaveFileSnapshot("MATCH SAVE FAILED");
464	    this._renderStatus(`MATCHED ${previousSheetId.toUpperCase()}`);
465	  }
466	
467	  private _applyState(values: AboutTheatreValue): void {
468	    const state = mergeAboutTheatreValue(values);
469	    this._rig.apply(this._engine, state);
470	    this._syncControlsToCameraState();
471	  }
472	
473	  private _readSheetEndValues(
474	    sheetId: AboutTheatreSheetId,
475	    object: AboutTheatreObject,
476	    sequence: TheatreSequencePort,
477	  ): AboutTheatreValue | null {
478	    const previousPosition = sequence.position;
479	    try {
480	      sequence.pause();
481	      sequence.position = this._resolveSheetEndPosition(sheetId, sequence);
482	      return pickAboutTheatreValue(mergeAboutTheatreValue(object.value));
483	    } catch (error) {
484	      Logger.warn(CLASS, "_readSheetEndValues", "Failed to read previous sheet end state.", error);
485	      return null;
486	    } finally {
487	      sequence.position = previousPosition;
488	    }
489	  }
490	
491	  private _writeMatchStartKeyframe(
492	    currentObject: AboutTheatreObject,
493	    currentSequence: TheatreSequencePort,
494	    previousValues: AboutTheatreValue,
495	  ): void {
496	    const previousPosition = currentSequence.position;
497	    const scrub = TheatreStudioService.createScrub<
498	      AboutTheatreValue,
499	      AboutTheatreProps
500	    >();
501	    currentSequence.pause();
502	    currentSequence.position = 0;
503	    scrub.capture(({ set }) => {
504	      set(currentObject.props, previousValues);
505	    });
506	    scrub.commit();
507	    currentSequence.position = previousPosition;
508	  }
509	
510	  private _resolveSheetEndPosition(
511	    sheetId: AboutTheatreSheetId,
512	    sequence: TheatreSequencePort,
513	  ): number {
514	    const saveFile = TheatreStudioService.createContentOfSaveFile(
515	      ABOUT_THEATRE_PROJECT_ID,
516	    );
517	    const sheetsById = this._readRecord(saveFile?.sheetsById);
518	    const sheetState = this._readRecord(sheetsById?.[sheetId]);
519	    const sequenceState = this._readRecord(sheetState?.sequence);
520	    const tracksByObject = this._readRecord(sequenceState?.tracksByObject);
521	    const objectTracks = this._readRecord(tracksByObject?.[ABOUT_THEATRE_OBJECT_ID]);
522	    const trackData = this._readRecord(objectTracks?.trackData);
523	    if (!trackData) {
524	      return sequence.length > 0 ? sequence.length : 0;
525	    }
526	
527	    let maxPosition = Number.NEGATIVE_INFINITY;
528	    Object.values(trackData).forEach((trackState) => {
529	      const trackRecord = this._readRecord(trackState);
530	      const keyframes = trackRecord?.keyframes;
531	      if (!Array.isArray(keyframes)) return;
532	      keyframes.forEach((keyframe) => {
533	        const keyframeRecord = this._readRecord(keyframe);
534	        const position = keyframeRecord?.position;
535	        if (typeof position !== "number" || !Number.isFinite(position)) return;
536	        maxPosition = Math.max(maxPosition, position);
537	      });
538	    });
539	
540	    if (!Number.isFinite(maxPosition)) {
541	      return sequence.length > 0 ? sequence.length : 0;
542	    }
543	    return maxPosition;
544	  }
545	
546	  private _syncControlsToCameraState(): void {
547	    const target = this._engine.getCameraTarget().position;
548	    this._controls.target.copy(target);
549	    this._controls.update();
550	  }
551	
552	  private _readSavedState(): Record<string, unknown> | null {
553	    return TheatreStateStorageService.read({
554	      ...ABOUT_THEATRE_STORAGE_OPTIONS,
555	      normalize: (state) => this._normalizeSavedState(state),
556	      validate: (state) => this._isReadableTheatreState(state),
557	    });
558	  }
559	
560	  private async _exportSaveFile(): Promise<void> {
561	    const raw = this._createSaveFileJson();
562	    if (raw == null) return;
563	    const persistedRaw =
564	      TheatreStateStorageService.readRaw(ABOUT_THEATRE_STORAGE_OPTIONS) ?? raw;
565	    if (!this._downloadSaveFile(persistedRaw, "about.json")) {
566	      this._renderStatus("EXPORT BLOCKED");
567	      return;
568	    }
569	    this._renderStatus("ABOUT.JSON DOWNLOADED");
570	  }
571	
572	  private _createSaveFileJson(failureStatus = "EXPORT FAILED"): string | null {
573	    const saveFile = TheatreStudioService.createContentOfSaveFile(
574	      ABOUT_THEATRE_PROJECT_ID,
575	    );
576	    if (!saveFile) {
577	      this._renderStatus(failureStatus);
578	      return null;
579	    }
580	    const minimizedSaveFile = this._minimizeSaveFile(saveFile);
581	    const raw = JSON.stringify(minimizedSaveFile, null, 2);
582	    TheatreStateStorageService.writeRaw(raw, ABOUT_THEATRE_STORAGE_OPTIONS);
583	    return raw;
584	  }
585	
586	  private _persistSaveFileSnapshot(failureStatus: string): void {
587	    this._createSaveFileJson(failureStatus);
588	  }
589	
590	  private _schedulePersistSaveFileSnapshot(failureStatus: string): void {
591	    if (typeof window === "undefined") {
592	      this._persistSaveFileSnapshot(failureStatus);
593	      return;
594	    }
595	    if (this._persistTimerId !== null) {
596	      window.clearTimeout(this._persistTimerId);
597	    }
598	    this._persistTimerId = window.setTimeout(() => {
599	      this._persistTimerId = null;
600	      this._persistSaveFileSnapshot(failureStatus);
601	    }, STORAGE_PERSIST_DELAY_MS);
602	  }
603	
604	  private _renderExportButton(): void {
605	    TheatreStudioService.renderAuthorButton(
606	      {
607	        id: EXPORT_BUTTON_ID,
608	        text: "EXPORT STATE JSON",
609	        bottom: "16px",
610	      },
611	      this._onExportClick,
612	    );
613	  }
614	
615	  private _renderSheetSelector(): void {
616	    TheatreStudioService.renderAuthorSelect(
617	      {
618	        id: SHEET_SELECT_ID,
619	        bottom: "92px",
620	        value: this._authorSheetId,
621	        options: ABOUT_THEATRE_SHEET_IDS.map((sheetId) => ({
622	          value: sheetId,
623	          text: sheetId,
624	        })),
625	      },
626	      this._onSheetChange,
627	    );
628	  }
629	
630	  private _renderMatchPrevButton(): void {
631	    TheatreStudioService.renderAuthorButton(
632	      {
633	        id: MATCH_PREV_BUTTON_ID,
634	        text: "MATCH FROM PREV",
635	        bottom: "130px",
636	      },
637	      this._onMatchPrevClick,
638	    );
639	  }
640	
641	  private _syncSheetSelector(): void {
642	    if (typeof document === "undefined") return;
643	    const select = document.getElementById(
644	      SHEET_SELECT_ID,
645	    ) as HTMLSelectElement | null;
646	    if (!select) return;
647	    select.value = this._authorSheetId;
648	  }
649	
650	  private _isTheatreSheetId(value: string): value is AboutTheatreSheetId {
651	    return (ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(value);
652	  }
653	
654	  private _renderStatus(text: string): void {
655	    TheatreStudioService.renderAuthorStatus(STATUS_ID, text);
656	  }
657	
658	  private _normalizeSavedState(
659	    savedState: Record<string, unknown>,
660	  ): Record<string, unknown> {
661	    const migratedState = this._migrateLegacySheetState(savedState);
662	    const sheetsById = this._readRecord(migratedState.sheetsById);
663	    const cameraSheet = this._readRecord(sheetsById?.[PRIMARY_SHEET_ID]);
664	    const sequence = this._readRecord(cameraSheet?.sequence);
665	    const staticOverrides = this._readRecord(sequence?.staticOverrides);
666	    const objectsByKey = this._readRecord(staticOverrides?.byObject);
667	    const cameraObject = this._readRecord(
668	      objectsByKey?.[ABOUT_THEATRE_OBJECT_ID],
669	    );
670	
671	    if (cameraObject) {
672	      const mergedValues = mergeAboutSceneState(
673	        cameraObject as Partial<typeof ABOUT_DEFAULT_SCENE_STATE>,
674	      );
675	      Object.assign(cameraObject, pickAboutTheatreValue(mergedValues));
676	    }
677	
678	    const projectDefinition = this._readRecord(
679	      savedState.definitionVersion != null ? savedState : null,
680	    );
681	    if (projectDefinition && projectDefinition.addressesBySheetId) {
682	      return { ...migratedState, projectId: ABOUT_THEATRE_PROJECT_ID };
683	    }
684	
685	    return migratedState;
686	  }
687	
688	  private _migrateLegacySheetState(
689	    savedState: Record<string, unknown>,
690	  ): Record<string, unknown> {
691	    const sheetsById = this._readRecord(savedState.sheetsById);
692	    if (!sheetsById) return savedState;
693	
694	    const nextSheetsById: Record<string, unknown> = {};
695	    let didChange = false;
696	
697	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
698	      const mappedSheetId =
699	        LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
700	      if (mappedSheetId !== sheetId) {
701	        didChange = true;
702	      }
703	      if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
704	        nextSheetsById[mappedSheetId] = sheetState;
705	        return;
706	      }
707	      didChange = true;
708	    });
709	
710	    if (!didChange) return savedState;
711	
712	    return {
713	      ...savedState,
714	      sheetsById: nextSheetsById,
715	    };
716	  }
717	
718	  private _readRecord(value: unknown): Record<string, unknown> | null {
719	    if (value == null || typeof value !== "object" || Array.isArray(value)) {
720	      return null;
721	    }
722	    return value as Record<string, unknown>;
723	  }
724	
725	  private _minimizeSaveFile(
726	    saveFile: Record<string, unknown>,
727	  ): Record<string, unknown> {
728	    const sheetsById = this._readRecord(saveFile.sheetsById);
729	    if (!sheetsById) return saveFile;
730	    const nextSheetsById: Record<string, unknown> = {};
731	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
732	      if (!this._isTheatreSheetId(sheetId)) return;
733	      const normalizedSheetState = this._normalizeSheetState(
734	        sheetState,
735	        sheetId,
736	      );
737	      if (!normalizedSheetState) return;
738	      nextSheetsById[sheetId] = normalizedSheetState;
739	    });
740	    return {
741	      ...saveFile,
742	      sheetsById: nextSheetsById,
743	    };
744	  }
745	
746	  private _normalizeSheetState(
747	    sheetState: unknown,
748	    sheetId: AboutTheatreSheetId,
749	  ): Record<string, unknown> | null {
750	    const sheetRecord = this._readRecord(sheetState);
751	    if (!sheetRecord) return null;
752	    if (this._sheetHasMeaningfulKeyframes(sheetRecord, sheetId)) {
753	      return sheetRecord;
754	    }
755	    return null;
756	  }
757	
758	  private _sheetHasMeaningfulKeyframes(
759	    sheetState: Record<string, unknown>,
760	    sheetId: AboutTheatreSheetId,
761	  ): boolean {
762	    const sequenceState = this._readRecord(sheetState.sequence);
763	    if (!sequenceState) return false;
764	    const tracksByObject = this._readRecord(sequenceState.tracksByObject);
765	    if (!tracksByObject) return false;
766	    const objectTracks = this._readRecord(tracksByObject[ABOUT_THEATRE_OBJECT_ID]);
767	    if (!objectTracks) return false;
768	    const trackData = this._readRecord(objectTracks.trackData);
769	    if (!trackData) return false;
770	    const sequence = this._sequenceBySheetId.get(sheetId);
771	    if (!sequence) return false;
772	    return Object.values(trackData).some((trackState) =>
773	      this._trackHasMeaningfulKeyframes(trackState, sequence),
774	    );
775	  }
776	
777	  private _trackHasMeaningfulKeyframes(
778	    trackState: unknown,
779	    sequence: TheatreSequencePort,
780	  ): boolean {
781	    const trackRecord = this._readRecord(trackState);
782	    if (!trackRecord) return false;
783	    const keyframes = trackRecord.keyframes;
784	    if (!Array.isArray(keyframes) || keyframes.length === 0) {
785	      return false;
786	    }
787	    const positions = keyframes
788	      .map((keyframe) => {
789	        const keyframeRecord = this._readRecord(keyframe);
790	        const position = keyframeRecord?.position;
791	        return typeof position === "number" && Number.isFinite(position)
792	          ? position
793	          : null;
794	      })
795	      .filter((position): position is number => position != null);
796	    return positions.length > 0;
797	  }
798	
799	  private _downloadSaveFile(raw: string, fileName: string): boolean {
800	    return TheatreStudioService.downloadFile(raw, { fileName });
801	  }
802	
803	  private _isReadableTheatreState(
804	    value: Record<string, unknown> | null,
805	  ): value is Record<string, unknown> {
806	    if (!value) return false;
807	    const sheetsById = value.sheetsById;
808	    if (
809	      sheetsById == null ||
810	      typeof sheetsById !== "object" ||
811	      Array.isArray(sheetsById)
812	    ) {
813	      return false;
814	    }
815	    return true;
816	  }
817	}
